// The sample photographs, by key. Point a key at your own photo (a path under public/ or a URL), or
// give a product new keys in data.ts. Installed, the samples load from dresscodeui.com.
// Product shots are on pure white: the cards blend them into the theme's card color.
const KEYS = [
  "apron-natural", "board-oak", "bottle-lineup", "bottle-stone", "bowls-oat", "candle", "duvet-oat", "jars", "kettle-black",
  "napkins-sage", "nonstick-cream", "pant-grey", "plates-sage", "plates-trio", "sheets-white", "skillet-clay", "soap",
  "sweater-charcoal", "sweater-moss", "sweater-oat", "tee-white", "throw-rust", "towel-sand", "weekender-olive",
  "model-front", "model-back", "knit-detail", "model-kitchen",
  "hero-table", "room-bedroom", "story-skillet", "story-workshop",
  "dept-kitchen", "dept-bedding", "dept-bath", "dept-apparel", "dept-bags", "dept-gifts",
  "post-linen-wash", "post-cast-iron", "post-linen-guide",
] as const

export const PHOTOS: Record<string, string> = Object.fromEntries(KEYS.map((k) => [k, `https://dresscodeui.com/ecommerce/${k}.webp`]))

/** Photos that are product shots on white (blended into the card), not scenes. */
export const ON_WHITE = new Set<string>(KEYS.slice(0, 24))

export const photo = (key: string) => PHOTOS[key] ?? key

// Pieces the pages share: photos (product shots blend into the card color), badges, prices, color
// dots, the product card in both looks and section headings.
import { ArrowRight } from "lucide-react"
import Link from "next/link"
import type { CSSProperties, ReactNode } from "react"

import { cn } from "@/lib/utils"

import { ON_WHITE, photo } from "./assets"
import { STORE, type Color, type Product, type Variant } from "./data"
import { coverOf, fromPrice, money, salePercent, stockOf, to } from "./site"
import { QuickAdd, SaveButton } from "./ui"

/** A photo that fills its box. Product shots on white sit in a "well" tinted to the theme and are
 *  blended into it (multiply), so the white disappears; scenes fill the box. */
export function Photo({ src, alt, className, imgClassName, priority, contain }: { src: string; alt: string; className?: string; imgClassName?: string; priority?: boolean; contain?: boolean }) {
  const white = ON_WHITE.has(src)
  return (
    <span className={cn("block size-full overflow-hidden", white && "ec-well", className)}>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={photo(src)}
        alt={alt}
        loading={priority ? "eager" : "lazy"}
        decoding="async"
        className={cn("size-full", white ? cn("mix-blend-multiply", contain ? "object-contain" : "object-cover") : "object-cover", src.startsWith("model") && "object-[50%_18%]", imgClassName)}
      />
    </span>
  )
}

export function Badge({ children, tone = "hl", className }: { children: ReactNode; tone?: "hl" | "sale" | "line"; className?: string }) {
  return (
    <span
      className={cn(
        "dc-pill h-6 px-2 text-[12px] font-semibold",
        tone === "hl" && "dc-pill-hl",
        tone === "sale" && "bg-[color:var(--dc-danger)] text-white",
        tone === "line" && "bg-card text-foreground shadow-[inset_0_0_0_1px_var(--border)]",
        className,
      )}
    >
      {children}
    </span>
  )
}

export function ProductBadge({ p, className }: { p: Product; className?: string }) {
  if (p.compareAt) return <Badge tone="sale" className={className}>{`Sale −${salePercent(p)}%`}</Badge>
  if (p.badge) return <Badge className={className}>{p.badge}</Badge>
  return null
}

export function Price({ p, size, className, exact }: { p: Product; size?: string; className?: string; exact?: boolean }) {
  const price = size ? (p.sizes?.find((s) => s.name === size)?.price ?? p.price) : undefined
  if (p.compareAt)
    return (
      <span className={cn("inline-flex items-baseline gap-2 tabular-nums", className)}>
        <span className="text-[color:var(--dc-danger)]">{money(price ?? p.price, exact)}</span>
        <s className="text-[0.88em] font-normal text-muted-foreground">{money(p.compareAt, exact)}</s>
        <span className="sr-only">, was {money(p.compareAt)}</span>
      </span>
    )
  return <span className={cn("tabular-nums", className)}>{price !== undefined ? money(price, exact) : fromPrice(p)}</span>
}

/** A color dot; checks are drawn as a small check. */
export function Dot({ color, className, style }: { color: Pick<Color, "hex" | "check" | "name">; className?: string; style?: CSSProperties }) {
  const check = color.check
    ? { backgroundImage: `linear-gradient(90deg, rgb(255 255 255 / 0.55) 50%, transparent 50%), linear-gradient(rgb(255 255 255 / 0.55) 50%, transparent 50%)`, backgroundSize: "50% 50%" }
    : undefined
  return <span className={cn("inline-block shrink-0 rounded-full shadow-[inset_0_0_0_1px_rgb(0_0_0/0.14)] dark:shadow-[inset_0_0_0_1px_rgb(255_255_255/0.28)]", className)} style={{ background: color.hex, ...check, ...style }} />
}

export function Dots({ colors, max = 4, className }: { colors: Color[]; max?: number; className?: string }) {
  if (!colors.length) return null
  const shown = colors.slice(0, max)
  return (
    <span className={cn("flex items-center gap-1.5", className)} aria-label={`${colors.length} colors: ${colors.map((c) => c.name).join(", ")}`} role="img">
      {shown.map((c) => (
        <Dot key={c.name} color={c} className="size-3.5" />
      ))}
      {colors.length > max ? <span className="text-[12px] text-muted-foreground">+{colors.length - max}</span> : null}
    </span>
  )
}

function lowStock(p: Product) {
  if (p.colors.length || p.sizes?.length) return null
  const n = stockOf(p)
  return n > 0 && n <= STORE.lowStock ? n : null
}

/** A product card. department: square-ish photo on the card color, bold name, dots and price; on
 *  hover a quick add rises. brand: a larger serif name and the color under it. */
export function ProductCard({ base, p, look = "department", className, priority, sizes = "md", hoverPhoto = true }: { base: string; p: Product; look?: Variant; className?: string; priority?: boolean; sizes?: "sm" | "md"; hoverPhoto?: boolean }) {
  const second = hoverPhoto ? p.photos[1] : undefined
  const low = lowStock(p)
  const brand = look === "brand"
  return (
    <article className={cn("group relative flex flex-col", brand && "h-full rounded-[var(--dc-radius-card)] border-[length:var(--dc-bw)] border-[color:var(--dc-card-border)] bg-card p-2 pb-3", className)}>
      <div
        className={cn(
          "ec-card-photo relative aspect-[4/3] overflow-hidden transition-shadow",
          brand ? "rounded-[calc(var(--dc-radius-card)-6px)]" : "rounded-[var(--dc-radius-card)] group-hover:shadow-[0_0_0_1.5px_var(--dc-primary)]",
        )}
      >
        <Photo src={coverOf(p)} alt={p.name} priority={priority} className="absolute inset-0 transition-transform duration-500 group-hover:scale-[1.03]" />
        {second ? <Photo src={second} alt="" className="absolute inset-0 opacity-0 transition-opacity duration-300 group-hover:opacity-100 max-md:hidden" /> : null}
        <ProductBadge p={p} className="absolute top-2.5 left-2.5 z-[1]" />
        <SaveButton slug={p.slug} label={p.name} className="absolute top-2 right-2 z-[2]" />
        <QuickAdd p={p} look={look} />
      </div>
      <div className={cn("flex flex-1 flex-col pt-3", brand && "px-2")}>
        <h3 className={cn(brand ? "dc-h text-[18px] leading-snug" : "text-[15px] leading-snug font-medium", sizes === "sm" && "text-[14px]")}>
          <Link href={to(base, "products", p.slug)} className="after:absolute after:inset-0 after:z-0 focus-visible:outline-none">
            {p.name}
          </Link>
        </h3>
        {brand && p.colors[0] ? <p className="mt-0.5 text-[13px] text-muted-foreground">{p.colors[0].name}</p> : null}
        <Dots colors={p.colors} className="mt-2" />
        <p className={cn("mt-auto flex items-baseline gap-2 pt-2 text-[15px]", !brand && "font-semibold")}>
          <Price p={p} />
          {low ? <span className="text-[13px] font-medium text-[color:var(--dc-danger)]">Only {low} left</span> : null}
        </p>
      </div>
    </article>
  )
}

/** A row card: photo left; name, price and colors right. For "You may also like". */
export function CompactCard({ base, p, className }: { base: string; p: Product; className?: string }) {
  return (
    <article className={cn("dc-card group relative flex items-center gap-4 p-2.5 transition-colors hover:border-foreground/30", className)}>
      <div className="aspect-square w-[42%] max-w-[132px] shrink-0 overflow-hidden rounded-[calc(var(--dc-radius-card)-4px)]">
        <Photo src={p.photos[0]} alt="" imgClassName="transition-transform duration-500 group-hover:scale-105" />
      </div>
      <div className="min-w-0 flex-1 py-1 pr-1">
        <h3 className="text-[15px] leading-snug font-semibold">
          <Link href={to(base, "products", p.slug)} className="after:absolute after:inset-0 focus-visible:outline-none">
            {p.name}
          </Link>
        </h3>
        <p className="mt-1.5 text-[15px]">
          <Price p={p} />
        </p>
        <Dots colors={p.colors} className="mt-3" />
      </div>
    </article>
  )
}

/** A small horizontal card: photo left, name and price right. */
export function MiniCard({ base, p, className, children }: { base: string; p: Product; className?: string; children?: ReactNode }) {
  return (
    <article className={cn("dc-card relative flex items-center gap-3 p-2.5", className)}>
      <div className="size-20 shrink-0 overflow-hidden rounded-[calc(var(--dc-radius-card)-4px)]">
        <Photo src={p.photos[0]} alt="" />
      </div>
      <div className="min-w-0 flex-1">
        <h3 className="text-[15px] leading-snug font-medium">
          <Link href={to(base, "products", p.slug)} className="after:absolute after:inset-0 focus-visible:outline-none">
            {p.name}
          </Link>
        </h3>
        <p className="mt-1 text-[14px] font-semibold">
          <Price p={p} />
        </p>
        {children}
      </div>
    </article>
  )
}

/** Section heading with an optional link (or anything) on the right. */
export function Section({ title, link, id, children, className, right, headingClassName }: { title: string; link?: { href: string; label: string }; id?: string; children: ReactNode; className?: string; right?: ReactNode; headingClassName?: string }) {
  return (
    <section aria-labelledby={id} className={className}>
      <div className="mb-4 flex flex-wrap items-end justify-between gap-3">
        <h2 id={id} className={cn("dc-h text-[clamp(1.5rem,2.4vw,1.9rem)] leading-tight", headingClassName)}>
          {title}
        </h2>
        {right}
        {link ? (
          <Link href={link.href} className="inline-flex items-center gap-1.5 text-[15px] font-medium text-[color:var(--dc-accent)] underline-offset-4 hover:underline">
            {link.label} <ArrowRight className="size-4" aria-hidden="true" />
          </Link>
        ) : null}
      </div>
      {children}
    </section>
  )
}

"use client"

// The cart: the drawer that slides in from the right whenever something is added, and the full cart
// page. Both read the same store (store.ts) and the same totals (site.ts).
import { ArrowRight, Gift, Lock, ShoppingBag, Truck } from "lucide-react"
import Link from "next/link"
import { useEffect, useState } from "react"

import { Sheet, SheetContent, SheetTitle } from "@/components/ui/sheet"
import { cn } from "@/lib/utils"

import { Photo } from "./cards"
import { DISCOUNTS, STORE, type Product } from "./data"
import { bestSelling, firstAvailable, isGiftCard, lineCover, lineName, linePrice, lineVariant, money, productOf, stockOf, to, totals, type Line } from "./site"
import { cart, drawer, useCart, useDrawer } from "./store"
import { FIELD, LINK, OUTLINE, PRIMARY } from "./styles"
import { Stepper } from "./ui"

/** "Your order ships free." or "You're $12.00 away from free shipping.", with a bar from $0 to $75. */
export function FreeShipping({ toFree, className }: { toFree: number; className?: string }) {
  const done = toFree <= 0
  const pct = Math.max(4, Math.min(100, ((STORE.freeShippingOver - toFree) / STORE.freeShippingOver) * 100))
  return (
    <div className={className}>
      <p className="text-[15px] font-medium">{done ? "Your order ships free." : <>You&apos;re {money(toFree, true)} away from free shipping.</>}</p>
      <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-muted" role="progressbar" aria-valuemin={0} aria-valuemax={STORE.freeShippingOver} aria-valuenow={STORE.freeShippingOver - toFree} aria-label="Toward free shipping">
        <div className="h-full rounded-full bg-primary transition-[width] duration-500" style={{ width: `${done ? 100 : pct}%` }} />
      </div>
      <div className="dc-num mt-1.5 flex justify-between text-[13px] text-muted-foreground">
        <span>$0</span>
        <span>{money(STORE.freeShippingOver)}</span>
      </div>
    </div>
  )
}

function GiftCardThumb({ className }: { className?: string }) {
  return (
    <span className={cn("grid size-full place-items-center bg-primary text-primary-foreground", className)}>
      <Gift className="size-6" aria-hidden="true" />
    </span>
  )
}

export function LineThumb({ line, className }: { line: Line; className?: string }) {
  return <span className={cn("block shrink-0 overflow-hidden rounded-[calc(var(--dc-radius-card)-4px)]", className)}>{isGiftCard(line) ? <GiftCardThumb /> : <Photo src={lineCover(line)} alt="" />}</span>
}

/** One line of the cart: photo, name, variant, quantity, remove, price. */
export function CartLine({ base, line, onNavigate, highlight }: { base: string; line: Line; onNavigate?: () => void; highlight?: boolean }) {
  const name = lineName(line)
  const href = isGiftCard(line) ? to(base, "gift-cards") : to(base, "products", line.slug)
  return (
    <li className={cn("flex gap-4 py-5 transition-colors", highlight && "ec-flash")}>
      <Link href={href} onClick={onNavigate} className="size-[84px]" tabIndex={-1} aria-hidden="true">
        <LineThumb line={line} className="size-[84px]" />
      </Link>
      <div className="min-w-0 flex-1">
        <div className="flex items-start justify-between gap-3">
          <Link href={href} onClick={onNavigate} className="text-[16px] leading-snug font-semibold hover:underline">
            {name}
          </Link>
          <span className="dc-num shrink-0 text-[16px] font-semibold">{money(linePrice(line) * line.qty, true)}</span>
        </div>
        {lineVariant(line) ? <p className="mt-1 text-[14px] text-muted-foreground">{lineVariant(line)}</p> : null}
        <div className="mt-3 flex items-center gap-4">
          <Stepper value={line.qty} onChange={(n) => cart.setQty(line.id, n)} label={name} size="sm" />
          <button type="button" onClick={() => cart.remove(line.id)} className="cursor-pointer text-[14px] text-muted-foreground underline underline-offset-4 hover:text-foreground">
            Remove
          </button>
        </div>
      </div>
    </li>
  )
}

/** Something that goes with what's in the cart and isn't in it yet: a small add-on that needs no size
 *  first (one click adds it), then anything that pairs, then a best seller. */
function upsellFor(lines: Line[]): Product | undefined {
  const inCart = new Set(lines.map((l) => l.slug))
  const pairs = lines.flatMap((l) => productOf(l.slug)?.pairs ?? []).map(productOf).filter((x): x is Product => !!x && !inCart.has(x.slug))
  return pairs.find((x) => !x.sizes?.length && x.price <= 60) ?? pairs[0] ?? bestSelling().find((p) => !inCart.has(p.slug))
}

function Upsell({ base, p, onNavigate }: { base: string; p: Product; onNavigate?: () => void }) {
  const first = firstAvailable(p)
  const color = first.color
  // Clothes start at M when there is one; everything else at its first size in stock.
  const size = p.sizes?.some((s) => s.name === "M") && stockOf(p, color, "M") > 0 ? "M" : first.size
  return (
    <div className="rounded-[var(--dc-radius-card)] bg-muted p-4">
      <p className="text-[15px] font-semibold">Pairs well with</p>
      <div className="mt-3 flex items-center gap-3">
        <Link href={to(base, "products", p.slug)} onClick={onNavigate} className="size-16 shrink-0 overflow-hidden rounded-[calc(var(--radius))]" tabIndex={-1} aria-hidden="true">
          <Photo src={p.photos[0]} alt="" />
        </Link>
        <div className="min-w-0 flex-1">
          <Link href={to(base, "products", p.slug)} onClick={onNavigate} className="block truncate text-[15px] font-medium hover:underline">
            {p.name}
          </Link>
          <p className="text-[13px] text-muted-foreground">{[color, size].filter(Boolean).join(" / ")}</p>
          <p className="dc-num text-[14px] font-semibold">{money(linePrice({ slug: p.slug, size }), true)}</p>
        </div>
        <button type="button" onClick={() => cart.add({ slug: p.slug, color, size }, { open: false })} className={cn(OUTLINE, "h-9 bg-card px-3 text-[14px]")}>
          + Add
        </button>
      </div>
    </div>
  )
}

function GiftNote() {
  const { giftNote, note } = useCart()
  return (
    <div>
      <label className="flex cursor-pointer items-center gap-3 text-[15px]">
        <input type="checkbox" checked={giftNote} onChange={(e) => cart.setGiftNote(e.target.checked)} className="size-5 accent-[color:var(--dc-primary)]" />
        Add a gift note
      </label>
      {giftNote ? (
        <textarea
          value={note}
          onChange={(e) => cart.setGiftNote(true, e.target.value)}
          maxLength={240}
          rows={3}
          placeholder="Happy birthday! Love, Sam"
          aria-label="Gift note"
          className={cn(FIELD, "mt-2 h-auto py-2")}
        />
      ) : null}
      {giftNote ? <p className="mt-1 text-[13px] text-muted-foreground">We&apos;ll print it on a card and leave out the receipt.</p> : null}
    </div>
  )
}

function EmptyCart({ base, onNavigate }: { base: string; onNavigate?: () => void }) {
  return (
    <div className="flex flex-1 flex-col items-center justify-center px-6 py-12 text-center">
      <span className="grid size-14 place-items-center rounded-full bg-muted">
        <ShoppingBag className="size-6" aria-hidden="true" />
      </span>
      <p className="dc-h mt-4 text-[22px]">Your cart is empty</p>
      <p className="mt-1 max-w-[26em] text-[15px] text-muted-foreground">Free shipping on orders over {money(STORE.freeShippingOver)}, and free returns for {STORE.returnDays} days.</p>
      <Link href={to(base, "shop")} onClick={onNavigate} className={cn(PRIMARY, "mt-6 h-11 px-5 text-[15px]")}>
        Shop best sellers
      </Link>
    </div>
  )
}

/** The drawer. Mounted once per page by the frame; `drawer.open()` slides it in. */
export function CartDrawer({ base }: { base: string }) {
  const { open, added } = useDrawer()
  const state = useCart()
  const t = totals(state.lines, { code: state.code })
  const upsell = state.lines.length ? upsellFor(state.lines) : undefined
  const close = () => drawer.close()
  return (
    <Sheet open={open} onOpenChange={(o) => (o ? drawer.open() : drawer.close())}>
      <SheetContent side="right" className="w-full gap-0 p-0 data-[side=right]:sm:max-w-[460px]" showCloseButton={false}>
        <div className="flex items-center gap-3 px-6 pt-6 pb-4">
          <SheetTitle className="dc-h text-[26px] leading-none">Your cart</SheetTitle>
          {t.count ? <span className="dc-num grid h-7 min-w-7 place-items-center rounded-full bg-muted px-2 text-[14px] font-semibold">{t.count}</span> : null}
          <button type="button" onClick={close} className="ml-auto grid size-9 cursor-pointer place-items-center rounded-full hover:bg-muted" aria-label="Close cart">
            <span aria-hidden="true" className="text-[22px] leading-none">
              ×
            </span>
          </button>
        </div>
        {!state.lines.length ? (
          <EmptyCart base={base} onNavigate={close} />
        ) : (
          <>
            <div className="flex-1 overflow-y-auto px-6">
              <FreeShipping toFree={t.toFree} className="border-b border-border pb-4" />
              <ul className="divide-y divide-border">
                {state.lines.map((l) => (
                  <CartLine key={l.id} base={base} line={l} onNavigate={close} highlight={l.id === added} />
                ))}
              </ul>
              <div className="grid gap-5 pb-6">
                {upsell ? <Upsell base={base} p={upsell} onNavigate={close} /> : null}
                <GiftNote />
              </div>
            </div>
            <div className="border-t border-border px-6 pt-4 pb-5">
              <div className="flex items-baseline justify-between text-[18px] font-semibold">
                <span>Subtotal</span>
                <span className="dc-num">{money(t.subtotal, true)}</span>
              </div>
              {t.discount ? (
                <p className="mt-1 flex justify-between text-[14px] text-muted-foreground">
                  <span>{state.code.toUpperCase()} applied at checkout</span>
                  <span className="dc-num">−{money(t.discount, true)}</span>
                </p>
              ) : null}
              <p className="mt-1 text-[14px] text-muted-foreground">Shipping and taxes calculated at checkout.</p>
              <Link href={to(base, "checkout")} onClick={close} className={cn(PRIMARY, "mt-4 h-[52px] w-full text-[17px]")}>
                Checkout · <span className="dc-num">{money(t.subtotal, true)}</span>
              </Link>
              <Link href={to(base, "cart")} onClick={close} className="mt-3 block text-center text-[14px] text-muted-foreground underline underline-offset-4 hover:text-foreground">
                View cart
              </Link>
            </div>
          </>
        )}
      </SheetContent>
    </Sheet>
  )
}

/** The code box: apply a discount code, or remove the one that's on. */
export function CodeBox({ className }: { className?: string }) {
  const { code } = useCart()
  const [draft, setDraft] = useState("")
  const [error, setError] = useState("")
  const apply = () => {
    const c = draft.trim().toUpperCase()
    if (!c) return
    if (DISCOUNTS[c]) {
      cart.setCode(c)
      setDraft("")
      setError("")
    } else setError("That code isn't valid. Check for typos, or try another.")
  }
  return (
    <div className={className}>
      <form
        className="flex gap-2"
        onSubmit={(e) => {
          e.preventDefault()
          apply()
        }}
      >
        <input value={draft} onChange={(e) => setDraft(e.target.value)} placeholder="Discount code or gift card" aria-label="Discount code" aria-invalid={!!error} aria-describedby={error ? "ec-code-error" : undefined} className={cn(FIELD, "uppercase placeholder:normal-case")} />
        <button type="submit" className={cn(OUTLINE, "h-11 bg-card px-4 text-[15px]")}>
          Apply
        </button>
      </form>
      {error ? (
        <p id="ec-code-error" className="mt-1.5 text-[13px] text-[color:var(--dc-danger)]">
          {error}
        </p>
      ) : null}
      {code && DISCOUNTS[code] ? (
        <p className="mt-2.5 flex items-center gap-2 text-[14px]">
          <span className="inline-flex h-8 items-center gap-2 rounded-[var(--radius)] bg-muted pr-1.5 pl-3 font-medium">
            {code}
            <button type="button" onClick={() => cart.setCode("")} className="grid size-5 cursor-pointer place-items-center rounded-full hover:bg-foreground/10" aria-label={`Remove ${code}`}>
              ×
            </button>
          </span>
          <span className="text-muted-foreground">{DISCOUNTS[code].label}</span>
        </p>
      ) : null}
    </div>
  )
}

/** The cart page: the lines on the left, the summary on the right. */
export function CartPageView({ base }: { base: string }) {
  const state = useCart()
  const t = totals(state.lines, { code: state.code })
