  const results = search(q)
  const value = draft ?? q
  return (
    <>
      <form
        role="search"
        onSubmit={(e) => {
          e.preventDefault()
          setDraft(null)
          router.push(`${to(base, "search")}?q=${encodeURIComponent(value.trim())}`)
