            {done ? "Added" : "+ Add"}
          </button>
        </div>
      </div>
    </li>
  )
}

export function PairsWellWith({ base, p }: { base: string; p: Product }) {
  const list = p.pairs.map(productOf).filter((x): x is Product => !!x)
  return (
    <ul className="grid gap-4 md:grid-cols-3">
      {list.map((x) => (
        <PairCard key={x.slug} base={base} p={x} />
      ))}
    </ul>
  )
}

