              {visible.length < list.length ? (
                <button type="button" onClick={() => setShown(shown + PAGE)} className={cn(OUTLINE, "mt-4 h-10 min-w-[160px] border-[color:var(--dc-accent)] px-5 text-[15px] text-[color:var(--dc-accent)]")}>
