            {recentList.map((p) => (
              <li key={p.slug}>
                <Link href={to(base, "products", p.slug)} className="dc-card flex items-center gap-4 overflow-hidden pr-4 hover:border-foreground/30">
                  <span className="h-16 w-24 shrink-0 overflow-hidden">
                    <Photo src={p.photos[0]} alt="" />
